import React from 'react';
import { NavLink } from 'react-router-dom';
//import classes from './NavigationItem.module.css';

const navigationItem = ( props ) => (
    <li class="nav-item">
        <NavLink 
            to={props.link}
            exact={props.exact}
            >{props.children}</NavLink>
    </li>
);

export default navigationItem;
